INSERT INTO `wp_options` VALUES (455,'options_about_page_vision_desc','“Memadukan amanah dan stabilitas keuangan sebagai fondasi utama, kami terus bergerak inovatif melalui pemanfaatan teknologi dan digitalisasi layanan modern untuk menghadirkan solusi perbankan yang sehat, andal, serta adaptif.s”','auto');
INSERT INTO `wp_options` VALUES (456,'options_about_page_missions','a:5:{i:0;s:35:\"Meningkatkan Kepercayaan dan Amanah\";i:1;s:42:\"Menjaga Kesehatan Keuangan dan Tata Kelola\";i:2;s:25:\"Mendorong Inovasi Layanan\";i:3;s:37:\"Memberdayakan UMKM dan Komunitas Umat\";i:4;s:34:\"Membangun Kedekatan dengan Nasabah\";}','auto');
INSERT INTO `wp_options` VALUES (457,'options_about_page_identity','BPRS Wakalumi adalah Lembaga Keuangan Syariah yang memiliki fokus pada jasa keuangan dan pemberdayaan ekonomi umat dan masyarakat sesuai syariah.','auto');
INSERT INTO `wp_options` VALUES (458,'options_about_page_belief','BPRS Wakalumi berkomitmen untuk selalu melakukan ISHLAH, yakni kami terus melakukan perbaikan berkelanjutan.','auto');
INSERT INTO `wp_options` VALUES (459,'options_about_page_values','a:4:{i:0;a:3:{s:7:\"acronym\";s:1:\"W\";s:5:\"title\";s:26:\"Wisdom (Fathanah & Siddiq)\";s:4:\"desc\";s:119:\"Menyoroti kearifan, integritas, dan kecerdasan dalam mengambil keputusan finansial berbasis syariah yang tepat sasaran.\";}i:1;a:3:{s:7:\"acronym\";s:1:\"A\";s:5:\"title\";s:23:\"Accountability (Amanah)\";s:4:\"desc\";s:131:\"Mencerminkan komitmen penuh terhadap transparansi, tata kelola yang bertanggung jawab, dan keandalan dalam memegang amanah nasabah.\";}i:2;a:3:{s:7:\"acronym\";s:1:\"Q\";s:5:\"title\";s:28:\"Quality (Tabligh & Fathanah)\";s:4:\"desc\";s:141:\"Menekankan keunggulan layanan, penyampaian komunikasi yang jelas, serta standar operasional terbaik demi memberikan manfaat berkesinambungan.\";}i:3;a:3:{s:7:\"acronym\";s:1:\"F\";s:5:\"title\";s:36:\"Foresight (Fathanah & Semangat Waqf)\";s:4:\"desc\";s:155:\"Menggambarkan visi jangka panjang yang berfokus pada inovasi, pertumbuhan produktif, dan keberlanjutan (sustainability) investasi untuk generasi mendatang.\";}}','auto');
