INSERT INTO `wp_options` VALUES (465,'options_about_page_logo_p2_desc','memiliki kedudukan kebahasaan dan spiritual yang sangat istimewa dalam Al-Quran. Selain sebagai simbol pengikat (waqaf atau penyambung), huruf ini mengandung berbagai makna mendalam secara linguistik, mukjizat rasam (penulisan), maupun tafsir.','auto');
