INSERT INTO `wp_options` VALUES (861,'options_pembiayaan_quote','Allah telah menghalalkan jual beli dan mengharamkan riba. (QS. Al-Baqarah: 275) — Berbisnis dan bermuamalah dengan penuh ketenangan, keadilan, dan keberkahan bagi seluruh pihak.','auto');
