INSERT INTO `wp_options` VALUES (949,'options_brosur_list','a:5:{i:0;a:10:{s:5:\"title\";s:34:\"Brosur Tabungan & Simpanan Syariah\";s:8:\"kategori\";s:17:\"Penghimpunan Dana\";s:5:\"badge\";s:16:\"Tabungan Syariah\";s:8:\"file_url\";s:0:\"\";s:9:\"file_size\";s:14:\"PDF • 1.8 MB\";s:5:\"cover\";s:0:\"\";s:4:\"desc\";s:118:\"Panduan lengkap Tabungan Tawakal, Tabungan Pendidikan, Tabungan Haji & Umroh, serta Tabungan Ukhuwah berhadiah berkah.\";s:7:\"version\";s:4:\"2026\";s:6:\"urutan\";i:1;s:5:\"color\";s:4:\"teal\";}i:1;a:10:{s:5:\"title\";s:36:\"Brosur Deposito Mudharabah Muthlaqah\";s:8:\"kategori\";s:17:\"Penghimpunan Dana\";s:5:\"badge\";s:18:\"Investasi Deposito\";s:8:\"file_url\";s:0:\"\";s:9:\"file_size\";s:14:\"PDF • 1.5 MB\";s:5:\"cover\";s:0:\"\";s:4:\"desc\";s:125:\"Penjelasan skema bagi hasil nisbah kompetitif, pilihan tenor 1-12 bulan, fasilitas ARO, dan penjaminan LPS hingga Rp2 Miliar.\";s:7:\"version\";s:4:\"2026\";s:6:\"urutan\";i:2;s:5:\"color\";s:5:\"amber\";}i:2;a:10:{s:5:\"title\";s:37:\"Brosur Pembiayaan 1000 Pedagang Pasar\";s:8:\"kategori\";s:15:\"Penyaluran Dana\";s:5:\"badge\";s:15:\"UMKM & Pedagang\";s:8:\"file_url\";s:0:\"\";s:9:\"file_size\";s:14:\"PDF • 2.1 MB\";s:5:\"cover\";s:0:\"\";s:4:\"desc\";s:125:\"Solusi permodalan usaha mikro pedagang pasar tradisional tanpa agunan rumit dengan angsuran harian atau mingguan yang ringan.\";s:7:\"version\";s:4:\"2026\";s:6:\"urutan\";i:3;s:5:\"color\";s:7:\"emerald\";}i:3;a:10:{s:5:\"title\";s:45:\"Brosur Pembiayaan 1000 Guru & Tenaga Pendidik\";s:8:\"kategori\";s:15:\"Penyaluran Dana\";s:5:\"badge\";s:12:\"Profesi Guru\";s:8:\"file_url\";s:0:\"\";s:9:\"file_size\";s:14:\"PDF • 1.9 MB\";s:5:\"cover\";s:0:\"\";s:4:\"desc\";s:138:\"Fasilitas pembiayaan multiguna syariah khusus guru dan tenaga kependidikan untuk renovasi rumah, pendidikan keluarga, dan kebutuhan halal.\";s:7:\"version\";s:4:\"2026\";s:6:\"urutan\";i:4;s:5:\"color\";s:4:\"blue\";}i:4;a:10:{s:5:\"title\";s:54:\"Ringkasan Akad Syariah (Murabahah, Mudharabah, Ijarah)\";s:8:\"kategori\";s:14:\"Program Khusus\";s:5:\"badge\";s:15:\"Edukasi Syariah\";s:8:\"file_url\";s:0:\"\";s:9:\"file_size\";s:14:\"PDF • 1.2 MB\";s:5:\"cover\";s:0:\"\";s:4:\"desc\";s:122:\"Materi literasi fikih muamalah perbankan syariah menjelaskan perbedaan mendasar prinsip syariah dengan bunga konvensional.\";s:7:\"version\";s:4:\"2026\";s:6:\"urutan\";i:5;s:5:\"color\";s:6:\"purple\";}}','auto');
