INSERT INTO `wp_options` VALUES (954,'options_brosur_gov_cards','a:3:{i:0;a:6:{s:5:\"badge\";s:14:\"Pengawasan OJK\";s:5:\"title\";s:23:\"Terdaftar & Diawasi OJK\";s:4:\"desc\";s:128:\"BPRS Wakalumi beroperasi di bawah pengawasan ketat Otoritas Jasa Keuangan (OJK) dengan mematuhi standar kehati-hatian perbankan.\";s:9:\"legal_ref\";s:32:\"Keputusan Otoritas Jasa Keuangan\";s:6:\"urutan\";i:1;s:5:\"color\";s:4:\"rose\";}i:1;a:6:{s:5:\"badge\";s:16:\"Jaminan Simpanan\";s:5:\"title\";s:23:\"Penjaminan Simpanan LPS\";s:4:\"desc\";s:136:\"Simpanan tabungan dan deposito nasabah dijamin keamanannya oleh Lembaga Penjamin Simpanan (LPS) hingga Rp 2 Miliar per nasabah per bank.\";s:9:\"legal_ref\";s:32:\"UU Penjaminan Simpanan Perbankan\";s:6:\"urutan\";i:2;s:5:\"color\";s:5:\"amber\";}i:2;a:6:{s:5:\"badge\";s:17:\"Kepatuhan Syariah\";s:5:\"title\";s:23:\"Kepatuhan Dewan Syariah\";s:4:\"desc\";s:137:\"Seluruh produk dan akad disupervisi langsung oleh Dewan Pengawas Syariah (DPS) tersertifikasi DSN-MUI untuk menjamin kemurnian dari riba.\";s:9:\"legal_ref\";s:32:\"Fatwa Dewan Syariah Nasional MUI\";s:6:\"urutan\";i:3;s:5:\"color\";s:7:\"emerald\";}}','auto');
