INSERT INTO `wp_options` VALUES (1145,'options_about_page_values_desc','Nilai-nilai perusahaan ditanamkan dalam cara berpikir, menjiwai pemahaman atas amanah dan tanggung jawab, termanifestasi dalam tindakan, serta menjadi landasan moral bagi setiap keputusan.\r\nBudaya organisasi terbentuk melalui praktik yang konsisten dan berkesinambungan. Ketika nilai-nilai tersebut telah mendarah daging, ia tidak lagi sekadar deklarasi, melainkan cara hidup BSW dalam berpikir, bertindak, dan menentukan arah.','auto');
